// ============================================
// Author:@南哥AGI研习社 (B站 or YouTube 搜索“南哥AGI研习社”)
// n8n Code节点 - 清洗数据
// ============================================

// 获取所有输入项
const items = $input.all();
// 提取第一项中的数据列表
const list = items[0].json.data.items;

// 遍历列表，为每个选题计算综合排名得分
const processedList = list.map(row => {
  // 获取发布时间的毫秒时间戳
  const pubMillis = row.fields["发布时间"]; // 毫秒时间戳

  // 返回处理后的选题对象
  return {
    记录ID: row.record_id,
    ID: row.fields["ID"],
    标题: row.fields["标题"][0].text,
    摘要: row.fields["摘要"][0].text,
    发布时间: DateTime.fromMillis(pubMillis).toFormat('yyyy/MM/dd HH:mm:ss'),
    来源名称: row.fields["来源名称"][0].text,
    来源类型: row.fields["来源类型"][0].text,
    原始链接: row.fields["原始链接"].link,
    机器标签: row.fields['机器标签'][0].text
  };
});

// 返回包含所有处理结果的数组
return [
  {
    json: {
      allResults: processedList,
    },
  },
];

// ============================================
// Author:@南哥AGI研习社 (B站 or YouTube 搜索“南哥AGI研习社”)
// n8n Code节点 - 对生成的富文本内容进行压缩成一行并进行转义（配合飞书消息服务使用）
// ============================================

const inputData = $input.all();
const feishuMessage = inputData[0].json;

// 提取post.zh_cn的完整对象
const postZhCn = {
    zh_cn: feishuMessage.content.post.zh_cn
};

// 转义函数
function escapeForFeishu(obj) {
    // 先转为标准JSON字符串(压缩格式)
    let jsonStr = JSON.stringify(obj);

    // 再次stringify并去掉最外层引号,实现转义
    let escapedStr = JSON.stringify(jsonStr);
    escapedStr = escapedStr.slice(1, -1);

    return escapedStr;
}

// 对内容进行转义
const escapedContent = escapeForFeishu(postZhCn);

// 构建最终输出
const result = {
    msg_type: "post",
    content: escapedContent
};

return { json: result };

// ============================================
// Author:@南哥AGI研习社 (B站 or YouTube 搜索“南哥AGI研习社”)
// n8n Code节点 - 飞书富文本消息生成器（兼容中文字段名输入 + 富文本美化）
// ============================================

const inputData = $input.all();
const data = inputData?.[0]?.json ?? {};

// 输入：第1层就有 output
const output = data.output ?? data?.[0]?.output ?? {};
const topHead = output.topHead || [];
const topQuick = output.topQuick || [];
const topDeep = output.topDeep || [];
const stats = output.stats || {};

// 工具：兼容中英字段名
const pick = (obj, keys, fallback = "") => {
  if (!obj) return fallback;
  for (const k of keys) {
    const v = obj[k];
    if (v !== undefined && v !== null && v !== "") return v;
  }
  return fallback;
};

// 工具：把标签字符串/数组统一成数组
const toTagArray = (v) => {
  if (!v) return [];
  if (Array.isArray(v)) return v.filter(Boolean);
  if (typeof v === "string") {
    return v
      .split(/[、,，;；|]/)
      .map((s) => s.trim())
      .filter(Boolean);
  }
  return [];
};

// 工具：摘要美化（按行拆分 + 识别小标题）
const splitSummaryLines = (summary) => {
  if (!summary || typeof summary !== "string") return [];
  const raw = summary.replace(/\r\n/g, "\n").replace(/\r/g, "\n").trim();
  if (!raw) return [];

  // 先按空行分段，再把段内按行拆开
  const paras = raw.split(/\n{2,}/g).map((p) => p.trim()).filter(Boolean);
  const lines = [];
  for (const p of paras) {
    const sub = p.split("\n").map((l) => l.trim()).filter(Boolean);
    if (sub.length === 1) lines.push(sub[0]);
    else lines.push(...sub);
    lines.push(""); // 段落间留空行
  }
  // 去掉末尾空行
  while (lines.length && lines[lines.length - 1] === "") lines.pop();
  return lines;
};

const isSectionHeader = (line) => {
  // 例如：一、核心要点 / 二、关键信息 / 1. xxx / 1、xxx / - xxx
  return (
    /^[一二三四五六七八九十]+、/.test(line) ||
    /^\d+\./.test(line) ||
    /^\d+、/.test(line) ||
    /^[-–—•]\s+/.test(line) ||
    /^【.+】$/.test(line)
  );
};

const content = [];

// 标题区
const formattedDateTime = $now.toFormat("yyyy/MM/dd HH:mm:ss");
content.push([{ tag: "text", text: `📊 AI公众号推文智能推送每日清单（${formattedDateTime}）\n`, style: ["bold"] }]);
content.push([{ tag: "text", text: "━━━━━━━━━━━━━━━━━━━━\n" }]);

// 数据概览
content.push([{ tag: "text", text: "📈 数据概览\n", style: ["bold"] }]);
content.push([{ tag: "text", text: `总计: ${stats.total ?? "-"} | 已处理: ${stats.processed ?? "-"}\n` }]);
content.push([
  {
    tag: "text",
    text: `头条: ${stats.head_count ?? topHead.length ?? 0} | 深度: ${stats.deep_count ?? topDeep.length ?? 0} | 快讯: ${stats.quick_count ?? topQuick.length ?? 0}\n\n`,
  },
]);

// 通用渲染
function renderItem(item, index) {
  const title = pick(item, ["标题", "title"], "(无标题)");
  const summary = pick(item, ["摘要", "summary"], "");
  const link = pick(item, ["原始链接", "source_link", "link", "url"], "");
  const sourceName = pick(item, ["来源名称", "source_name"], "");
  const sourceType = pick(item, ["来源类型", "source_type"], "");
  const publishTime = pick(item, ["发布时间", "publish_time", "published_at"], "");
  const tags = toTagArray(pick(item, ["机器标签", "tags", "machine_tags"], ""));
  const reason = pick(item, ["reason", "分配原因", "allocation_reason"], "");

  // 标题
  content.push([{ tag: "text", text: `${index + 1}. ${title}\n`, style: ["bold"] }]);

  // 来源信息（更紧凑）
  const srcParts = [];
  if (sourceName) srcParts.push(sourceName);
  if (sourceType) srcParts.push(sourceType);
  if (publishTime) srcParts.push(publishTime);
  if (srcParts.length) content.push([{ tag: "text", text: `   📰 ${srcParts.join(" | ")}\n` }]);

  // 原文链接（单独一行）
  if (link) {
    content.push([
      { tag: "text", text: "   🔗 原文: " },
      { tag: "a", text: "点击查看", href: link },
      { tag: "text", text: "\n" },
    ]);
  }

  // 标签（更短更清爽）
  if (tags.length) content.push([{ tag: "text", text: `   🏷️ 标签: ${tags.join("、")}\n` }]);

  // 推荐理由（先于摘要）
  if (reason) content.push([{ tag: "text", text: `   🧭 推荐理由: ${reason}\n` }]);

  // 摘要（放在推荐理由下面 + 美化）—— 取消摘要展示部分的文字加粗
  if (summary) {
    content.push([{ tag: "text", text: "   📄 摘要\n" }]);

    const lines = splitSummaryLines(summary);
    for (const line of lines) {
      if (!line) {
        content.push([{ tag: "text", text: "   \n" }]);
        continue;
      }

      if (isSectionHeader(line)) {
        content.push([{ tag: "text", text: `   ${line}\n` }]);
      } else {
        // 普通行：轻缩进
        content.push([{ tag: "text", text: `     ${line}\n` }]);
      }
    }
  }

  // 条目间分隔
  content.push([{ tag: "text", text: "\n" }]);
}

// =====================
// 头条
// =====================
if (topHead.length > 0) {
  content.push([{ tag: "text", text: "📰 头条\n", style: ["bold"] }]);
  content.push([{ tag: "text", text: "━━━━━━━━━━━━━━━━━━━━\n" }]);
  topHead.forEach((item, index) => renderItem(item, index));
}

// =====================
// 深度
// =====================
if (topDeep.length > 0) {
  content.push([{ tag: "text", text: "📖 深度\n", style: ["bold"] }]);
  content.push([{ tag: "text", text: "━━━━━━━━━━━━━━━━━━━━\n" }]);
  topDeep.forEach((item, index) => renderItem(item, index));
}

// =====================
// 快讯
// =====================
if (topQuick.length > 0) {
  content.push([{ tag: "text", text: "⚡ 快讯\n", style: ["bold"] }]);
  content.push([{ tag: "text", text: "━━━━━━━━━━━━━━━━━━━━\n" }]);
  topQuick.forEach((item, index) => renderItem(item, index));
}

// 系统链接
content.push([{ tag: "text", text: "\n━━━━━━━━━━━━━━━━━━━━\n" }]);
content.push([
  { tag: "text", text: "🔗 " },
  {
    tag: "a",
    text: "点击进入系统查看更过AI公众号推文详情",
    href: "https://mcn33lfbwjgi.feishu.cn/base/ZyoUbGafqaPrbds2SHMcePgAnSh?table=tbl3pZv5Kg8hji0U&view=vewCrySxh8",
  },
  { tag: "text", text: "\n" },
]);

const feishuMessage = {
  msg_type: "post",
  content: {
    post: {
      zh_cn: {
        title: "🤖 AI公众号推文采集和智能推送支持平台",
        content,
      },
    },
  },
};

return { json: feishuMessage };

// ============================================
// Author:@南哥AGI研习社 (B站 or YouTube 搜索“南哥AGI研习社”)
// n8n Code节点 - 回去记录的record_id及对应的推荐类型进行多维表格数据更新
// ============================================

// 获取上一个节点的输出数据
const inputData = $input.all()[0].json.output;

// 定义原始键名与中文名称的映射关系
const mapping = {
  'topHead': '头条',
  'topQuick': '快讯',
  'topDeep': '深度'
};

let results = [];

// 遍历映射关系
for (const [key, chineseName] of Object.entries(mapping)) {
  const records = inputData[key];

  // 如果该分类下有数据且是数组，则提取 record_id
  if (records && Array.isArray(records)) {
    records.forEach(record => {
      results.push({
        json: {
          record_id: record.记录ID,
          record_flag: chineseName // 使用对应的中文名称
        }
      });
    });
  }
}

// 返回符合 n8n 标准结构的数组
return results;
